package me.rerere.lastchat.ios.backup

/**
 * A real SQLite database produced by the same toolchain as an Android backup export:
 * the backed-up ConversationEntity and MemoryEntity tables, with a nodes payload large
 * enough to exercise overflow-page chains.
 */
internal val IOS_BACKUP_DB_FIXTURE: ByteArray = base64Decoded(IOS_BACKUP_DB_FIXTURE_BASE64)

private fun base64Decoded(value: String): ByteArray {
    val chars = value.filterNot { it.isWhitespace() }
    val bytes = ByteArray(chars.length * 3 / 4)
    var out = 0
    var buffer = 0
    var bits = 0
    for (char in chars) {
        val symbol = when (char) {
            in 'A'..'Z' -> char - 'A'
            in 'a'..'z' -> char - 'a' + 26
            in '0'..'9' -> char - '0' + 52
            '+' -> 62
            '/' -> 63
            else -> continue
        }
        buffer = (buffer shl 6) or symbol
        bits += 6
        if (bits >= 8) {
            bits -= 8
            bytes[out++] = ((buffer shr bits) and 0xFF).toByte()
        }
    }
    return bytes.copyOf(out)
}

private const val IOS_BACKUP_DB_FIXTURE_BASE64 = """"""
